  const goalRates=[mir,branchMir,sir,branchSir],goalNotes=[m.p?progressText(num(d.general),m.individualMerc):'Meta diária ainda não distribuída',m.p?progressText(num(d.general),m.branchMerc):'Referência ainda não distribuída',m.p?progressText(services,m.individualServices):'Meta diária ainda não distribuída',m.p?progressText(services,m.branchServices):'Referência ainda não distribuída'];
