  const serviceCommission=Object.prototype.hasOwnProperty.call(d,'commissionService')?num(d.commissionService):services*.05;
  const values=[num(d.invoiceCount)?brl.format(ticket):'—',brl.format(services),num(d.nfs)?pct.format(conv):'—',num(d.eligible)?pct.format(eff):'—',brl.format(mercCommission),brl.format(serviceCommission),brl.format(mercCommission+serviceCommission)];
  values.forEach((v,i)=>{if(rs[i])rs[i].textContent=v});
  if(rs[2])rs[2].className=statusClass(conv/.35);
  if(rs[3])rs[3].className=statusClass(eff/.07);
  const reached=!!(m.p&&m.individualMerc&&m.individualServices&&num(d.general)>=m.individualMerc&&services>=m.individualServices);
