  const gridPos=hasNeg?[top,(top+zeroY)/2,zeroY,(zeroY+H-bottom)/2,H-bottom]:Array.from({length:5},(_,i)=>top+(plotH*i/4));
  const grid=gridPos.map((yy,i)=>{const lv=hasNeg?(i===0?mPos:i===1?mPos/2:i===2?0:i===3?mNeg/2:mNeg):mPos*(1-i/4),rv=hasNeg?(i===0?ePos:i===1?ePos/2:i===2?0:i===3?eNeg/2:eNeg):ePos*(1-i/4);return `<line x1="${left}" y1="${yy}" x2="${W-right}" y2="${yy}" stroke="#e7edf4"/><text x="8" y="${yy+4}" fill="#718096" font-size="10">${dashAxisFmt(lv,'merc')}</text><text x="${W-right+8}" y="${yy+4}" fill="#718096" font-size="10">${Number(rv).toFixed(1).replace('.',',')}%</text>`}).join('');
