  const bars=rows.map(([,d],i)=>{const vals=[merc[i],eff[i]],maps=[ym,ye],colors=[['#1688ec','#6550e8'],['#f59e0b','#f7c55c']],cx=left+(i+.5)*unit,base=cx-groupW/2;return vals.map((v,j)=>{const xx=base+j*(bw+gap),yv=maps[j](v),yy=Math.min(zeroY,yv),hh=Math.max(2,Math.abs(zeroY-yv)),labelY=v>=0?Math.max(top+12,yy-(expanded?(j===0?(i%2?22:9):(i%2?9:22)):8)):Math.min(H-bottom-4,yy+hh+(expanded?(j===0?(i%2?24:14):(i%2?14:24)):14)),tone=j===0?'#1268bd':'#b66b00',txt=j===0?brl.format(v):`${Number(v).toFixed(2).replace('.',',')}%`;return `<defs><linearGradient id="dual-${i}-${j}-${expanded?1:0}" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${colors[j][0]}"/><stop offset="1" stop-color="${colors[j][1]}"/></linearGradient></defs><rect x="${xx}" y="${yy}" width="${bw}" height="${hh}" rx="4" fill="url(#dual-${i}-${j}-${expanded?1:0})"/><text x="${xx+bw/2}" y="${labelY}" text-anchor="middle" fill="${tone}" font-size="${expanded?8.2:6.4}" font-weight="900" style="paint-order:stroke;stroke:#fff;stroke-width:${expanded?3:2}px;stroke-linejoin:round">${txt}</text>`}).join('')}).join('');
