function ensureDashModal(){let m=document.getElementById('sellerDashModal');if(m)return m;m=document.createElement('div');m.id='sellerDashModal';m.className='dash-modal';m.hidden=true;m.dataset.landscapeLock='0';m.dataset.landscapeFullscreen='0';m.innerHTML='<div class="dash-modal-dialog" role="dialog" aria-modal="true"><div class="dash-modal-head"><strong id="sellerDashModalTitle">Gráfico</strong><button type="button" class="dash-modal-close" aria-label="Fechar">×</button></div><div class="dash-modal-body"></div></div>';document.body.appendChild(m);const close=async()=>{const state={locked:m.dataset.landscapeLock==='1',fullscreen:m.dataset.landscapeFullscreen==='1'};m.hidden=true;m.classList.remove('mobile-landscape','virtual-landscape');document.body.classList.remove('dash-modal-open');m.dataset.landscapeLock='0';m.dataset.landscapeFullscreen='0';await releaseSellerLandscape(state)};m.querySelector('.dash-modal-close').addEventListener('click',close);m.addEventListener('click',e=>{if(e.target===m)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden)close()});return m}
function openDashModal(card){
  if(!card)return;
  const m=ensureDashModal(),title=card.querySelector('h3')?.textContent?.trim()||'Gráfico',body=m.querySelector('.dash-modal-body');
  m.querySelector('#sellerDashModalTitle').textContent=title;body.innerHTML='';
  const clone=card.cloneNode(true);clone.querySelectorAll('[data-dash-expand]').forEach(x=>x.remove());clone.classList.add('dash-card-expanded');
  let values=String(card.dataset.chartValues||'').split(',').filter(Boolean).map(Number),labels=String(card.dataset.chartLabels||'').split(',').filter(Boolean),metric=card.dataset.chartMetric||'merc',type=card.dataset.chartType||'bar',statusFlags=String(card.dataset.chartStatus||'').split(',');
  const oldSvg=clone.querySelector('.dash-svg');if(oldSvg&&values.length){const wrap=document.createElement('div');wrap.innerHTML=dashSvg(values,labels,type,metric,true,statusFlags);const svg=wrap.firstElementChild;if(svg)oldSvg.replaceWith(svg)}
  body.appendChild(clone);const landscape=shouldUseSellerLandscapeModal();ensureSellerLandscapeFallbackCss();m.classList.toggle('mobile-landscape',landscape);m.classList.remove('virtual-landscape');m.hidden=false;document.body.classList.add('dash-modal-open');requestAnimationFrame(async()=>{const dialog=m.querySelector('.dash-modal-dialog');if(dialog){dialog.scrollTop=0;dialog.scrollLeft=0}const state=await requestSellerLandscape(dialog);m.dataset.landscapeLock=state.locked?'1':'0';m.dataset.landscapeFullscreen='0';m.classList.toggle('virtual-landscape',landscape&&!state.locked)})
}
